package com.pocketmusic.android;
import android.app.*;
import android.content.*;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.*;
import java.util.*;
import java.lang.reflect.*;
import static org.junit.Assert.*;
/** Opt-in public music streaming, muted; never uses a real account or saves audio. */
public class LiveOnlineAudioTest {
 @Test public void publicAudioPlaysAfterHomeWithoutWritingMusicFile()throws Exception{
  Assume.assumeTrue("Opt-in public stream","true".equals(InstrumentationRegistry.getArguments().getString("liveOnline")));Instrumentation test=InstrumentationRegistry.getInstrumentation();Context context=test.getTargetContext();assertFalse("Use an account-free emulator",YouTubeSession.connected(context));int before=MusicRepository.files(context).size();List<Track> songs=MusicCatalog.songs("Daft Punk Get Lucky","live-online-catalogue");assertFalse("No current public music fixture",songs.isEmpty());Track track=songs.get(0);
  TestMusicFixtures.Snapshot snapshot=new TestMusicFixtures.Snapshot(context);OnlineAudio.Resolver original=LocalPlayerService.onlineResolver;MainActivity[] activity={null};
  try{if("true".equals(InstrumentationRegistry.getArguments().getString("nativeOnly")))LocalPlayerService.onlineResolver=(c,t,p)->{long begin=android.os.SystemClock.elapsedRealtime();OnlineAudio.Source result=MusicCatalog.audio(t.id,p);System.out.println("RESOLVE_MS="+(android.os.SystemClock.elapsedRealtime()-begin));return result;};long started=android.os.SystemClock.elapsedRealtime();context.getSharedPreferences("music",0).edit().putInt("volume",0).remove("playerError").commit();TestMusicFixtures.seed(context,List.of(track));if(android.os.Build.VERSION.SDK_INT>=33)test.getUiAutomation().grantRuntimePermission(context.getPackageName(),android.Manifest.permission.POST_NOTIFICATIONS);activity[0]=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));test.runOnMainSync(()->{try{Method play=MainActivity.class.getDeclaredMethod("playTrack",Track.class,List.class);play.setAccessible(true);play.invoke(activity[0],track,List.of(track));}catch(Exception e){throw new AssertionError(e);}});context.startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));long end=System.currentTimeMillis()+95000;while((LocalPlayerService.active==null||!LocalPlayerService.active.playing()||LocalPlayerService.active.position()<250)&&System.currentTimeMillis()<end){if(!context.getSharedPreferences("music",0).getString("playerError","").isEmpty())break;Thread.sleep(100);}System.out.println("STARTUP_MS="+(android.os.SystemClock.elapsedRealtime()-started));LocalPlayerService player=LocalPlayerService.active;assertNotNull("Public audio did not open: "+context.getSharedPreferences("music",0).getString("playerError",""),player);assertTrue("Public audio is not playing",player.playing());context.startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));int position=player.position();Thread.sleep(1500);assertTrue("Public audio stopped after Home",player.position()>position+600);assertTrue(player.networkPlayback);if(!"true".equals(InstrumentationRegistry.getArguments().getString("nativeOnly"))){long replay=android.os.SystemClock.elapsedRealtime();OnlineAudio.resolve(context,track,"live-replay");long elapsed=android.os.SystemClock.elapsedRealtime()-replay;System.out.println("CACHED_RESOLVE_MS="+elapsed);assertTrue("Replay repeated network extraction",elapsed<1000);}assertEquals(before,MusicRepository.files(context).size());}
  finally{test.runOnMainSync(()->{context.stopService(new Intent(context,LocalPlayerService.class));if(activity[0]!=null)activity[0].finish();});long end=System.currentTimeMillis()+5000;while(LocalPlayerService.active!=null&&System.currentTimeMillis()<end)Thread.sleep(50);LocalPlayerService.onlineResolver=original;snapshot.restore();}
 }
 @Test public void publicPreparedQueueSwitchReusesPlayerInBackground()throws Exception{
  Assume.assumeTrue("Opt-in public queue","true".equals(InstrumentationRegistry.getArguments().getString("liveQueue")));Instrumentation test=InstrumentationRegistry.getInstrumentation();Context context=test.getTargetContext();assertFalse(YouTubeSession.connected(context));Assume.assumeTrue("Requires eligible unmetered network",LocalPlayerService.warmAllowed.test(context));List<Track> found=MusicCatalog.songs("Daft Punk Get Lucky","live-queue-catalogue");assertTrue(found.size()>=2);List<Track> tracks=found.subList(0,2);for(Track track:tracks)OnlineAudio.forget(context,track.id);int files=MusicRepository.files(context).size();TestMusicFixtures.Snapshot snapshot=new TestMusicFixtures.Snapshot(context);MainActivity[] activity={null};
  try{context.getSharedPreferences("music",0).edit().putInt("volume",0).remove("playerError").commit();TestMusicFixtures.seed(context,tracks);test.getUiAutomation().grantRuntimePermission(context.getPackageName(),android.Manifest.permission.POST_NOTIFICATIONS);activity[0]=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));long first=android.os.SystemClock.elapsedRealtime();test.runOnMainSync(()->{try{Method play=MainActivity.class.getDeclaredMethod("playTrack",Track.class,List.class);play.setAccessible(true);play.invoke(activity[0],tracks.get(0),tracks);}catch(Exception e){throw new AssertionError(e);}});context.startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));long end=System.currentTimeMillis()+95000;while((LocalPlayerService.active==null||!LocalPlayerService.active.playing())&&System.currentTimeMillis()<end)Thread.sleep(100);LocalPlayerService service=LocalPlayerService.active;assertNotNull(service);assertTrue(service.playing());System.out.println("LIVE_QUEUE_FIRST_MS="+(android.os.SystemClock.elapsedRealtime()-first));Field field=LocalPlayerService.class.getDeclaredField("player");field.setAccessible(true);AudioPlayer player=(AudioPlayer)field.get(service);end=System.currentTimeMillis()+10000;while(!player.preloadReady&&System.currentTimeMillis()<end)Thread.sleep(100);Field jobField=LocalPlayerService.class.getDeclaredField("warmJob");jobField.setAccessible(true);java.util.concurrent.Future<?> pending=(java.util.concurrent.Future<?>)jobField.get(service);Field upcoming=AudioPlayer.class.getDeclaredField("upcoming");upcoming.setAccessible(true);System.out.println("WARM_ATTACHED="+(upcoming.get(player)!=null)+" PLAY_STATE="+service.state+" WARM_ERROR="+player.preloadFailure+" WARM_TASK="+(pending==null?"none":pending.isDone()?(pending.get()==null?"empty":"source"):"running"));assertNotNull("Next public source did not resolve",pending);assertTrue("Next source still resolving",pending.isDone());assertNotNull("Next source unavailable",pending.get());System.out.println("WARM_AUDIO_READY="+player.preloadReady);long next=android.os.SystemClock.elapsedRealtime();test.runOnMainSync(service::next);end=System.currentTimeMillis()+10000;while((!service.playing()||!service.song.id.equals(tracks.get(1).id)||service.position()<250)&&System.currentTimeMillis()<end)Thread.sleep(50);long elapsed=android.os.SystemClock.elapsedRealtime()-next;System.out.println("LIVE_PREPARED_NEXT_MS="+elapsed);assertTrue(service.playing());assertEquals(tracks.get(1).id,service.song.id);assertSame(player,field.get(service));assertTrue("Prepared public switch remained slow",elapsed<5000);int position=service.position();Thread.sleep(1200);assertTrue(service.position()>position+500);assertEquals(files,MusicRepository.files(context).size());}
  finally{test.runOnMainSync(()->{context.stopService(new Intent(context,LocalPlayerService.class));if(activity[0]!=null)activity[0].finish();});long end=System.currentTimeMillis()+5000;while(LocalPlayerService.active!=null&&System.currentTimeMillis()<end)Thread.sleep(50);snapshot.restore();}
 }
}
